void * qla8044_read_optrom_data ( struct scsi_qla_host * vha , void * buf , uint32_t offset , uint32_t length ) { scsi_block_requests ( vha -> host , NULL ) ; if ( qla8044_read_flash_data ( vha , buf , offset , length / 4 ) != QLA_SUCCESS ) { ql_log ( ql_log_warn , vha , 0xb08d , "%s: Failed to read from flash\n" , __func__ ) ; } scsi_unblock_requests ( vha -> host ) ; return buf ; } 